function power(x: number, n: number): number {
  if (n < 0) return power(1 / x, -n); // safe in JS: -(-2^31) fits in a double
  if (n === 0) return 1;
  const half = power(x, Math.floor(n / 2));
  return n % 2 === 1 ? half * half * x : half * half;
}

