function power(x: number, n: number): number {
  let e = n;
  if (e < 0) { x = 1 / x; e = -e; }
  let result = 1;
  while (e > 0) {
    if (e % 2 === 1) result *= x;
    x *= x;
    e = Math.floor(e / 2); // not e >> 1: that breaks at 2^31
  }
  return result;
}

